  Syntagma(id: 'con-plura-001', text: '<pater> et [māter] {laeta} est', lemmaId: 'laetus', casus: Casus.nominativus, number: Numerus.singularis, gender: Gender.femininum, head: 'mater', candidates: ['pater'], tags: {'con-plura'}, note: 'Laeta nōminātīvus fēminīnus singulāris: cum proximō nōmine māter congruit.'),
  Syntagma(id: 'con-plura-002', text: '<Mārcus> et [Iūlia] {pulchra} est', lemmaId: 'pulcher', casus: Casus.nominativus, number: Numerus.singularis, gender: Gender.femininum, head: 'iulia', candidates: ['marcus'], tags: {'con-plura'}, note: 'Pulchra nōminātīvus fēminīnus singulāris: sōla Iūlia congruit.'),
  Syntagma(id: 'con-plura-003', text: '<puella> et [puer] {parvus} in hortō lūdunt', lemmaId: 'parvus', casus: Casus.nominativus, number: Numerus.singularis, gender: Gender.masculinum, head: 'puer', candidates: ['puella'], tags: {'con-plura'}, note: 'Parvus nōminātīvus masculīnus singulāris: puer, nōn puella.'),
  Syntagma(id: 'con-plura-004', text: '<servī> et [ancillae] {laetae} cantant', lemmaId: 'laetus', casus: Casus.nominativus, number: Numerus.pluralis, gender: Gender.femininum, head: 'ancilla', candidates: ['servus'], tags: {'con-plura'}, note: 'Laetae nōminātīvus fēminīnus plūrālis: ancillae; servī masculīnum est.'),
  Syntagma(id: 'con-plura-005', text: '<Iūlia> et [Mārcus] {improbus} in hortō sunt', lemmaId: 'improbus', casus: Casus.nominativus, number: Numerus.singularis, gender: Gender.masculinum, head: 'marcus', candidates: ['iulia'], tags: {'con-plura'}, note: 'Improbus nōminātīvus masculīnus singulāris: Mārcus sōlus improbus est.'),
  Syntagma(id: 'con-plura-006', text: '<vīlla> et [hortus] {magnus} Iūliī sunt', lemmaId: 'magnus', casus: Casus.nominativus, number: Numerus.singularis, gender: Gender.masculinum, head: 'hortus', candidates: ['villa'], tags: {'con-plura'}, note: 'Magnus nōminātīvus masculīnus singulāris: hortus, nōn vīlla.'),
  Syntagma(id: 'con-plura-007', text: '<templum> et [mūrus] {altus} in oppidō sunt', lemmaId: 'altus', casus: Casus.nominativus, number: Numerus.singularis, gender: Gender.masculinum, head: 'murus', candidates: ['templum'], tags: {'con-plura'}, note: 'Altus nōminātīvus masculīnus singulāris: mūrus; templum neutrum est.'),
  Syntagma(id: 'con-plura-008', text: '<rosae> et [māla] {rubra} in mēnsā sunt', lemmaId: 'ruber', casus: Casus.nominativus, number: Numerus.pluralis, gender: Gender.neutrum, head: 'malum', candidates: ['rosa'], tier: 1, tags: {'con-plura'}, note: 'Rubra nōminātīvus neuter plūrālis: māla; rosae fēminīnum est.'),
