  Syntagma(id: 'con-plura-010', text: '<dominus> et [domina] {bona} servōs amant', lemmaId: 'bonus', casus: Casus.nominativus, number: Numerus.singularis, gender: Gender.femininum, head: 'domina', candidates: ['dominus'], tags: {'con-plura'}, note: 'Bona nōminātīvus fēminīnus singulāris: domina.'),
  Syntagma(id: 'con-plura-011', text: '<servus> et <ancilla> [dominum] {sevērum} timent', lemmaId: 'severus', casus: Casus.accusativus, number: Numerus.singularis, gender: Gender.masculinum, head: 'dominus', candidates: ['servus', 'ancilla'], tier: 1, tags: {'con-plura'}, note: 'Sevērum accūsātīvus masculīnus singulāris: dominum timent.'),
  Syntagma(id: 'con-plura-012', text: 'Iūlius <Iūliae> et [Quīntō] {aegrō} māla dat', lemmaId: 'aeger', casus: Casus.dativus, number: Numerus.singularis, gender: Gender.masculinum, head: 'quintus_n', candidates: ['iulia'], tier: 1, tags: {'con-plura'}, note: 'Aegrō datīvus masculīnus singulāris: Quīntō; Iūliae fēminīnum est.'),
  // (b) plural adjective agreeing with coordinated nouns.
  Syntagma(id: 'con-plura-013', text: 'pater et māter {laetī} sunt', lemmaId: 'laetus', casus: Casus.nominativus, number: Numerus.pluralis, gender: Gender.masculinum, tags: {'con-plura'}, note: 'Laetī nōminātīvus masculīnus plūrālis: persōnae dīversī generis masculīnum plūrāle capiunt.'),
  Syntagma(id: 'con-plura-014', text: 'Mārcus et Quīntus {improbī} sunt', lemmaId: 'improbus', casus: Casus.nominativus, number: Numerus.pluralis, gender: Gender.masculinum, tags: {'con-plura'}, note: 'Improbī nōminātīvus masculīnus plūrālis: duo puerī.'),
  Syntagma(id: 'con-plura-015', text: 'puerī et puellae {laetī} in hortō lūdunt', lemmaId: 'laetus', casus: Casus.nominativus, number: Numerus.pluralis, gender: Gender.masculinum, tags: {'con-plura'}, note: 'Laetī masculīnum plūrāle: puerī et puellae simul masculīnō genere dīcuntur.'),
  Syntagma(id: 'con-plura-016', text: 'mūrus et templum {alta} sunt', lemmaId: 'altus', casus: Casus.nominativus, number: Numerus.pluralis, gender: Gender.neutrum, tier: 2, tags: {'con-plura'}, note: 'Alta nōminātīvus neuter plūrālis: rēs dīversī generis neutrum plūrāle capiunt.'),
  Syntagma(id: 'con-plura-017', text: 'Iūlius et Aemilia {bonī} parentēs sunt', lemmaId: 'bonus', casus: Casus.nominativus, number: Numerus.pluralis, gender: Gender.masculinum, tags: {'con-plura'}, note: 'Bonī nōminātīvus masculīnus plūrālis: vir et fēmina masculīnō genere.'),
  Syntagma(id: 'con-plura-018', text: 'Aemilia et Iūlia {pulchrae} sunt', lemmaId: 'pulcher', casus: Casus.nominativus, number: Numerus.pluralis, gender: Gender.femininum, tags: {'con-plura'}, note: 'Pulchrae nōminātīvus fēminīnus plūrālis: ambae fēminae sunt.'),
  Syntagma(id: 'con-plura-019', text: 'pater Mārcum et Quīntum {improbōs} pūnit', lemmaId: 'improbus', casus: Casus.accusativus, number: Numerus.pluralis, gender: Gender.masculinum, tier: 1, tags: {'con-plura'}, note: 'Improbōs accūsātīvus masculīnus plūrālis: Mārcum et Quīntum pūnit.'),
  Syntagma(id: 'con-plura-020', text: 'māter Iūliae et Mārcō {aegrīs} remedium dat', lemmaId: 'aeger', casus: Casus.dativus, number: Numerus.pluralis, gender: Gender.masculinum, tier: 2, tags: {'con-plura'}, note: 'Aegrīs datīvus masculīnus plūrālis: fēmina et vir simul masculīnō genere.'),
  Syntagma(id: 'con-plura-021', text: 'gladius et scūtum {gravia} sunt', lemmaId: 'gravis', casus: Casus.nominativus, number: Numerus.pluralis, gender: Gender.neutrum, tier: 2, tags: {'con-plura'}, note: 'Gravia nōminātīvus neuter plūrālis: rēs masculīna et neutra neutrum plūrāle capiunt.'),
  Syntagma(id: 'con-plura-022', text: 'cum Mārcō et Quīntō {laetīs} Iūlia lūdit', lemmaId: 'laetus', casus: Casus.ablativus, number: Numerus.pluralis, gender: Gender.masculinum, tier: 1, tags: {'con-plura'}, note: 'Laetīs ablātīvus masculīnus plūrālis post cum: Mārcō et Quīntō.'),

