  Syntagma(id: 'con-appositio-004', text: 'cum [Dāvō], {servō} bonō, Mārcus ambulat', lemmaId: 'servus', casus: Casus.ablativus, number: Numerus.singularis, head: 'davus', functio: Functio.appositio, tags: {'con-appositio'}, note: 'Servō appositiō ablātīvō Dāvō post cum apposita.'),
  Syntagma(id: 'con-appositio-005', text: '[Syra], {ancilla} Aemiliae, Iūliam vocat', lemmaId: 'ancilla', casus: Casus.nominativus, number: Numerus.singularis, head: 'syra', functio: Functio.appositio, tags: {'con-appositio'}, note: 'Ancilla appositiō nōminātīvō Syra apposita: Syra vocat.'),
  Syntagma(id: 'con-appositio-006', text: 'Iūlius [Mēdum], {servum} improbum, quaerit', lemmaId: 'servus', casus: Casus.accusativus, number: Numerus.singularis, head: 'medus', functio: Functio.appositio, tags: {'con-appositio'}, note: 'Servum appositiō accūsātīvō Mēdum apposita: Mēdus quaeritur.'),
  Syntagma(id: 'con-appositio-007', text: '[Quīntī], {fīliī} Iūliī, pēs aeger est', lemmaId: 'filius', casus: Casus.genetivus, number: Numerus.singularis, head: 'quintus_n', functio: Functio.appositio, tier: 1, tags: {'con-appositio'}, note: 'Fīliī appositiō genetīvō Quīntī apposita: pēs Quīntī.'),
  Syntagma(id: 'con-appositio-008', text: '[Mārce], {fīlī} improbe, tacē!', lemmaId: 'filius', casus: Casus.vocativus, number: Numerus.singularis, head: 'marcus', functio: Functio.appositio, tier: 2, tags: {'con-appositio'}, note: 'Fīlī appositiō vocātīvō Mārce apposita: Mārcus vocātur.'),
  Syntagma(id: 'con-appositio-009', text: 'in [Italiā], {terrā} pulchrā, Rōma est', lemmaId: 'terra', casus: Casus.ablativus, number: Numerus.singularis, head: 'italia', functio: Functio.appositio, tags: {'con-appositio'}, note: 'Terrā appositiō ablātīvō Italiā post in apposita.'),
  Syntagma(id: 'con-appositio-010', text: 'Aemilia [Iūliae], {fīliae} suae, rosam dat', lemmaId: 'filia', casus: Casus.dativus, number: Numerus.singularis, head: 'iulia', functio: Functio.appositio, tier: 1, tags: {'con-appositio'}, note: 'Fīliae appositiō datīvō Iūliae apposita: Iūliae rosa datur.'),
  Syntagma(id: 'con-appositio-011', text: '[Tiberis], {fluvius} Rōmānus, in mare fluit', lemmaId: 'fluvius', casus: Casus.nominativus, number: Numerus.singularis, head: 'tiberis', functio: Functio.appositio, tags: {'con-appositio'}, note: 'Fluvius appositiō nōminātīvō Tiberis apposita: Tiberis fluit.'),
  Syntagma(id: 'con-appositio-012', text: '[Iūlium], {dominum} sevērum, servī timent', lemmaId: 'dominus', casus: Casus.accusativus, number: Numerus.singularis, head: 'iulius', functio: Functio.appositio, tags: {'con-appositio'}, note: 'Dominum appositiō accūsātīvō Iūlium apposita: Iūlius timētur.'),
  Syntagma(id: 'con-appositio-013', text: '[Dāvus] et Mēdus, {servī} Iūliī, in hortō sunt', lemmaId: 'servus', casus: Casus.nominativus, number: Numerus.pluralis, head: 'davus', functio: Functio.appositio, tier: 1, tags: {'con-appositio'}, note: 'Servī appositiō plūrālis duōbus nōminibus nōminātīvīs apposita.'),
  Syntagma(id: 'con-appositio-014', text: '[Mārcus] et Quīntus, {puerī} improbī, pugnant', lemmaId: 'puer', casus: Casus.nominativus, number: Numerus.pluralis, head: 'marcus', functio: Functio.appositio, tier: 1, tags: {'con-appositio'}, note: 'Puerī appositiō nōminātīvō plūrālī Mārcus et Quīntus apposita.'),
  Syntagma(id: 'con-appositio-015', text: 'Iūlius [Athēnās], {urbem} Graecam, videt', lemmaId: 'urbs', casus: Casus.accusativus, number: Numerus.singularis, head: 'athenae', functio: Functio.appositio, tier: 2, tags: {'con-appositio'}, note: 'Urbem appositiō accūsātīvō Athēnās apposita: singulāris, quamquam Athēnae plūrāle est.'),
  // Contrast: the noun is not an apposition.
  Syntagma(id: 'con-appositio-016', text: 'Iūlius {patrem} vocat', lemmaId: 'pater', casus: Casus.accusativus, number: Numerus.singularis, functio: Functio.obiectum, tags: {'con-appositio'}, note: 'Patrem obiectum verbī vocat, nōn appositiō: nūllum nōmen eōdem cāsū adest.'),
  Syntagma(id: 'con-appositio-017', text: '{Iūlius} pater Mārcī est', lemmaId: 'iulius', casus: Casus.nominativus, number: Numerus.singularis, functio: Functio.subiectum, tags: {'con-appositio'}, note: 'Iūlius subiectum verbī est: quis pater Mārcī sit dīcitur.'),
  Syntagma(id: 'con-appositio-018', text: 'Iūlius {pater} Mārcī est', lemmaId: 'pater', casus: Casus.nominativus, number: Numerus.singularis, functio: Functio.praedicatum, tier: 1, tags: {'con-appositio'}, note: 'Pater praedicātīvum cum verbō est, nōn appositiō: Iūlius, pater Mārcī, venit appositiōnem habēret.'),
  Syntagma(id: 'con-appositio-019', text: '{Mārce}, venī!', lemmaId: 'marcus', casus: Casus.vocativus, number: Numerus.singularis, functio: Functio.vocatio, tags: {'con-appositio'}, note: 'Mārce vocātiō: puer vocātur, nūllī nōminī appositus.'),
  Syntagma(id: 'con-appositio-020', text: 'Aemilia {mātrī} rosam dat', lemmaId: 'mater', casus: Casus.dativus, number: Numerus.singularis, functio: Functio.datum, tags: {'con-appositio'}, note: 'Mātrī datīvus: cui rosa datur, nōn appositiō.'),
  Syntagma(id: 'con-appositio-021', text: 'Mārcus fīlius {Iūliī} est', lemmaId: 'iulius', casus: Casus.genetivus, number: Numerus.singularis, functio: Functio.possessor, tier: 1, tags: {'con-appositio'}, note: 'Iūliī genetīvus possessōris: fīlius Iūliī, nōn appositiō.'),
  Syntagma(id: 'con-appositio-022', text: 'Aemilia {ancillam} vocat', lemmaId: 'ancilla', casus: Casus.accusativus, number: Numerus.singularis, functio: Functio.obiectum, tags: {'con-appositio'}, note: 'Ancillam obiectum verbī vocat.'),
  Syntagma(id: 'con-appositio-023', text: '{servī}, tacēte!', lemmaId: 'servus', casus: Casus.vocativus, number: Numerus.pluralis, functio: Functio.vocatio, tier: 1, tags: {'con-appositio'}, note: 'Servī vocātiō plūrālis: imperātīvus tacēte servōs vocat.'),
  Syntagma(id: 'con-appositio-024', text: '{Dāvus} servus Iūliī est', lemmaId: 'davus', casus: Casus.nominativus, number: Numerus.singularis, functio: Functio.subiectum, tags: {'con-appositio'}, note: 'Dāvus subiectum: servus praedicātīvum est, nōn appositiō.'),
